def is_balanced(text):
    stack = []
    openers = {'(', '[', '{'}
    closers = {')': '(', ']': '[', '}': '{'}
    for char in text:
        if char in openers:
            stack.append(char)
        elif char in closers:
            if not stack or stack[-1] != closers[char]:
                return False
            stack.pop()
    return not stack
